    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address tokenOwner, uint tokens) public payable {
        require(true);
        address tokenAddress = address(this); // our fallback returns no data -> transfer result decodes to false
        bool obs = c.transferAnyERC20Token(tokenAddress, tokenOwner, tokens); if (__ESBMC_reverted()) return;
        assert(obs == false);
    }
    receive() external payable {}
    fallback() external payable {}
}

